#!/usr/bin/env dotnet
// Explore Friday the 13th in the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
DateOnly earliest = default;
for (int year = 1; year <= 9999; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            goto found;
        }
    }
}
found:
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// Count Friday the 13ths in a full 400-year Gregorian cycle (the calendar repeats every 400 years)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle (0001–0400): {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month across the 400-year cycle
Console.WriteLine("\nDistribution by month:");
for (int month = 1; month <= 12; month++)
{
    int mc = 0;
    for (int year = 1; year <= 400; year++)
    {
        if (new DateOnly(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            mc++;
    }
    Console.WriteLine($"  {new DateOnly(2000, month, 1):MMMM,-12} {mc}");
}

